mapper.insert:
insert into project_record_task (
	project_record_no,
	task_no
)
values (
	#{projectRecordNo},
	#{taskNo}
)

insert into project_record_message (
	project_record_no,
	chat_message_no
)
values (
	#{projectRecordNo},
	#{chatMessageNo}
)

insert into project_record_note (
	project_record_no,
	note_no
)
values (
	#{projectRecordNo},
	#{noteNo}
)

insert into project_record_attach (
	project_record_no,
	attach_no
)
values (
	#{projectRecordNo},
	#{attachNo}
)

mapper.sql:
where pr.project_no = #{projectNo}
and pr.project_record_type = #{request.type}
and pr.project_record_type = 'ISSUE' and pri.issue_status = #{request.issueStatus}
and pr.project_record_writer_no = #{request.writerNo}
and pr.project_record_ctime >= #{request.startDate}
and pr.project_record_ctime < #{request.endDate} + 1
and exists ( select 1 from project_record_task prt where prt.project_record_no = pr.project_record_no )
and exists ( select 1 from project_record_message prm where prm.project_record_no = pr.project_record_no )
and exists ( select 1 from project_record_note prn where prn.project_record_no = pr.project_record_no )
and exists ( select 1 from project_record_attach pra where pra.project_record_no = pr.project_record_no )
and (
lower(pr.project_record_title) like '%' || lower(#{request.keyword}) || '%'
or dbms_lob.instr( lower(pr.project_record_content), lower(#{request.keyword}) ) > 0
or exists ( select 1 from project_record_task prt join task t on prt.task_no = t.task_no where prt.project_record_no = pr.project_record_no and lower(t.task_title) like '%' || lower(#{request.keyword}) || '%' )
or exists ( select 1 from project_record_note prn join note n on prn.note_no = n.note_no where prn.project_record_no = pr.project_record_no and lower(n.note_title) like '%' || lower(#{request.keyword}) || '%' )
or exists ( select 1 from project_record_attach pra join attach a on pra.attach_no = a.attach_no where pra.project_record_no = pr.project_record_no and lower(a.attach_name) like '%' || lower(#{request.keyword}) || '%' )
or exists ( select 1 from project_record_message prm join chat_message cm on prm.chat_message_no = cm.chat_message_no where prm.project_record_no = pr.project_record_no and lower(cm.chat_message_content) like '%' || lower(#{request.keyword}) || '%' )
)
